    void checkProducer() throws Exception {
        var fixture=new BslLeanChecksMain();fixture.dir=dir;
        fixture.setup();
        try {
            Files.copy(Path.of("dev/upstream/other-pack-research/MakeUp-UltraFast-9.5g.zip"),dir.resolve("Original.zip"),StandardCopyOption.REPLACE_EXISTING);
