  Files.copy(Path.of("dev/upstream/other-pack-research/MakeUp-UltraFast-9.5g.zip"),dir.resolve("MakeUp.zip"));
  options=dir.resolve("MakeUp.zip.txt");Files.write(options,prior);Files.setPosixFilePermissions(options,intended);
