package com.pp.shaderlod.integration;

import static org.junit.jupiter.api.Assertions.*;
import com.pp.shaderlod.LodPreset;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Files;
import java.util.Properties;
import java.util.Map;
import org.junit.jupiter.api.Test;

/** Runs with root's integrated main source. Pure fixture checks also run without Gradle. */
class RasterExperimentTransactionTest {
    public static void main(String[] args) throws Exception {
        new RasterExperimentTransactionTest().actualTransactionEarlyRouteAndRecoveryDefersRejectedQueue();
        System.out.println("PASS actual PackSelectionTransaction early route and deferred recovery queue");
        new RasterExperimentTransactionTest().exactIrisWriterLifecycleChecks();
    }
    static final class Backend implements PackSelectionTransaction.Backend {
        final RasterExperimentSelectionFixtureCheck.Fixture fixture;
        Backend(RasterExperimentSelectionFixtureCheck.Fixture fixture) { this.fixture = fixture; }
        public Path directory() { return fixture.directory; }
        public String selected() { return fixture.backend.selected(); }
        public Map<String, String> queue() { return fixture.backend.queue(); }
        public Map<String, String> effectiveOptions() { return fixture.nativeMap; }
        public RasterExperimentSelection.RuntimePins privateRasterRuntime() {
            return RasterExperimentSelectionFixtureCheck.RUNTIME;
        }
        public void select(String name) { fixture.backend.select(name); }
        public void save() throws IOException { fixture.backend.save(); }
    }
    @Test void fixtureTransactionCases() throws Exception { RasterExperimentSelectionFixtureCheck.main(new String[0]); }
    @Test void actualTransactionEarlyRouteAndRecoveryDefersRejectedQueue() throws Exception {
        String previous = System.getProperty(RasterExperimentSelection.OPT_IN);
        System.setProperty(RasterExperimentSelection.OPT_IN, "true");
        try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
            var before = f.snapshot(); var backend = new Backend(f);
            backend.queue().put("PBR_MODE", "2");
            var action = new PackSelectionTransaction(backend);
            assertTrue(action.prepare(true, LodPreset.PERFORMANCE));
            assertEquals("Experiment.zip", backend.selected());
            assertTrue(backend.queue().isEmpty());
            action.restoreForRecovery();
            assertTrue(action.requiresOwnedNativeRecovery());
            f.unchanged(before); assertEquals("Original.zip", backend.selected());
            assertTrue(backend.queue().isEmpty(), "Rejected edits withheld from native recovery reload");
            action.recoveryReload(() -> {
                assertTrue(backend.queue().isEmpty());
                RasterIrisWriterFixture.write(f.directory.resolve("Original.zip.txt"));
            });
            action.finishRecovery(); assertEquals(Map.of("PBR_MODE", "2"), backend.queue());
        } finally {
            if (previous == null) System.clearProperty(RasterExperimentSelection.OPT_IN);
            else System.setProperty(RasterExperimentSelection.OPT_IN, previous);
        }
    }
    @FunctionalInterface interface Action { void run() throws Exception; }
    static void refused(Action action) throws Exception {
        try { action.run(); fail("Expected transaction refusal"); } catch (IOException | IllegalStateException expected) { }
    }
    @Test void exactIrisWriterLifecycleChecks() throws Exception {
        String previous = System.getProperty(RasterExperimentSelection.OPT_IN);
        System.setProperty(RasterExperimentSelection.OPT_IN, "true");
        try {
            RasterIrisWriterFixture.initialize();
            try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
                var prior = f.snapshot(); var action = new PackSelectionTransaction(new Backend(f));
                f.backend.queue.put("PBR_MODE", "2"); // Captured by helper's admission below, not outer construction.
                action.prepare(true, LodPreset.PERFORMANCE);
                refused(() -> action.reload(() -> {
                    RasterIrisWriterFixture.write(f.directory.resolve("Experiment.zip.txt"));
                    throw new IOException("Injected driver rejection after normal writer");
                }));
                action.restoreForRecovery(); f.unchanged(prior); assertTrue(f.backend.queue.isEmpty());
                action.recoveryReload(() -> RasterIrisWriterFixture.write(f.directory.resolve("Original.zip.txt")));
                f.unchanged(prior); action.finishRecovery(); assertEquals("2", f.backend.queue.get("PBR_MODE"));
            }
            System.out.println("PASS failed candidate reload after exact writer, exact recovery and rejected queue deferral");
            for (int mode = 0; mode < 3; mode++) try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
                if (mode == 1) Files.delete(f.directory.resolve("Original.zip.txt"));
                byte[] desired = mode == 1 ? null : Files.readAllBytes(f.directory.resolve("Original.zip.txt"));
                var permissions = mode == 1 ? null : Files.getPosixFilePermissions(f.directory.resolve("Original.zip.txt"));
                f.apply(true, LodPreset.PERFORMANCE);
                var action = new PackSelectionTransaction(new Backend(f)); action.prepare(false, LodPreset.PERFORMANCE);
                final int writerMode = mode;
                action.reload(() -> {
                    var properties = writerMode == 0 ? new Properties() : RasterIrisWriterFixture.read(f.directory.resolve("Original.zip.txt"));
                    if (writerMode == 1) properties.setProperty("TAA", "true");
                    RasterIrisWriterFixture.write(f.directory.resolve("Original.zip.txt"), properties);
                });
                if (desired == null) assertFalse(Files.exists(f.directory.resolve("Original.zip.txt")));
                else {
                    assertArrayEquals(desired, Files.readAllBytes(f.directory.resolve("Original.zip.txt")));
                    assertEquals(permissions, Files.getPosixFilePermissions(f.directory.resolve("Original.zip.txt")));
                }
                assertEquals("Original.zip", f.backend.selected);
            }
            System.out.println("PASS successful Off preserves original bytes/mode/absence across deletion, creation and normalization");
            try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
                f.apply(true, LodPreset.PERFORMANCE); var prior = f.snapshot();
                var action = new PackSelectionTransaction(new Backend(f)); action.prepare(true, LodPreset.QUALITY);
                refused(() -> action.reload(() -> {
                    RasterIrisWriterFixture.write(f.directory.resolve("Original.zip.txt"), new Properties());
                    throw new IOException("Rejected Quality");
                }));
                action.restoreForRecovery(); f.unchanged(prior);
                action.recoveryReload(() -> RasterIrisWriterFixture.write(f.directory.resolve("Experiment.zip.txt")));
                f.unchanged(prior); action.finishRecovery(); assertEquals("Experiment.zip", f.backend.selected);
            }
            System.out.println("PASS rejected Quality/Off returns candidate and recovery normalization restores exact prior sidecar");
            for (boolean returning : new boolean[]{false, true}) try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
                if (returning) f.apply(true, LodPreset.PERFORMANCE);
                var prior = f.snapshot(); var action = new PackSelectionTransaction(new Backend(f));
                action.prepare(!returning, LodPreset.PERFORMANCE);
                refused(() -> action.reload(() -> RasterIrisWriterFixture.write(f.directory.resolve(
                        f.backend.selected + ".txt"), RasterIrisWriterFixture.partial())));
                action.restoreForRecovery(); f.unchanged(prior);
                action.recoveryReload(() -> RasterIrisWriterFixture.write(f.directory.resolve(f.backend.selected + ".txt")));
                f.unchanged(prior); action.finishRecovery();
            }
            System.out.println("PASS swallowed partial writer I/O owns afterimage and restores exact enable/Off preimages");
            try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
                var action = f.open(); Files.writeString(f.directory.resolve("Original.zip.txt"), "TAA=false\n");
                refused(() -> action.prepare(true, LodPreset.PERFORMANCE, f.nativeMap));
                assertFalse(Files.exists(f.directory.resolve("Experiment.zip.txt")));
                assertEquals("TAA=false\n", Files.readString(f.directory.resolve("Original.zip.txt")));
            }
            System.out.println("PASS original edit after admission refuses stale TAA copy before any writes");
            for (String name : new String[]{"Original.zip", "Experiment.zip", "Original.zip.txt", "Experiment.zip.txt",
                    RasterExperimentSelection.RECEIPT, "selection", "queue"}) try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
                var action = new PackSelectionTransaction(new Backend(f)); action.prepare(true, LodPreset.PERFORMANCE);
                if (name.equals("selection")) f.backend.selected = "External.zip";
                else if (name.equals("queue")) f.backend.queue.put("EXTERNAL", "9");
                else Files.writeString(f.directory.resolve(name), "External change\n");
                boolean[] dispatched = {false}; refused(() -> action.reload(() -> dispatched[0] = true));
                assertFalse(dispatched[0], name);
            }
            System.out.println("PASS reload revalidates both archives, all sidecars/receipt, selection and queue");
            try (var f = new RasterExperimentSelectionFixtureCheck.Fixture(false)) {
                var action = new PackSelectionTransaction(new Backend(f)); action.prepare(true, LodPreset.PERFORMANCE);
                int calls = RasterIrisWriterFixture.invocations;
                refused(() -> action.reload(() -> {
                    Files.writeString(f.directory.resolve("Experiment.zip.txt"), "EXTERNAL=9\n");
                    RasterIrisWriterFixture.write(f.directory.resolve("Experiment.zip.txt"));
                }));
                assertEquals(calls, RasterIrisWriterFixture.invocations, "HEAD guard stopped pinned writer");
