package com.pp.shaderlod.integration;

import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;
import java.util.jar.JarFile;
import org.objectweb.asm.ClassReader;
import org.objectweb.asm.ClassVisitor;
import org.objectweb.asm.ClassWriter;
import org.objectweb.asm.MethodVisitor;
import org.objectweb.asm.Opcodes;

/** Executes only the exact pinned Iris filesystem writer, not Iris initialization/GL.
 * HEAD/RETURN callbacks simulate the corresponding exact private mixin entry points.
 */
final class RasterIrisWriterFixture {
    private static Method exactWriter;
    static int invocations;
    static void initialize() throws Exception {
        if (exactWriter != null) return;
        Path path = Path.of("dev/runtime/iris-neoforge-1.8.12+mc1.21.1.jar");
        if (!RasterExperimentSelection.IRIS.equals(RasterExperimentSelection.hashFile(path)))
            throw new AssertionError("Exact Iris fixture artifact changed");
        byte[] source;
        try (var archive = new JarFile(path.toFile())) {
            source = archive.getInputStream(archive.getJarEntry("net/irisshaders/iris/Iris.class")).readAllBytes();
        }
        var output = new ClassWriter(0);
        output.visit(Opcodes.V21, Opcodes.ACC_PUBLIC, "ExactRasterIrisWriter", null, "java/lang/Object", null);
        new ClassReader(source).accept(new ClassVisitor(Opcodes.ASM9) {
            @Override public MethodVisitor visitMethod(int access, String name, String descriptor,
                    String signature, String[] exceptions) {
                if (!name.equals("tryUpdateConfigPropertiesFile")) return null;
                return output.visitMethod(Opcodes.ACC_PUBLIC | Opcodes.ACC_STATIC, name, descriptor, signature, exceptions);
            }
        }, 0);
        output.visitEnd(); byte[] code = output.toByteArray();
        Files.write(Path.of("dev/logs/cross-shader-performance-r1/raster-transaction/ExactRasterIrisWriter.class"), code);
        Class<?> type = new ClassLoader() {
            Class<?> define() { return defineClass("ExactRasterIrisWriter", code, 0, code.length); }
        }.define();
        exactWriter = type.getMethod("tryUpdateConfigPropertiesFile", Path.class, Properties.class);
        System.out.println("PROVENANCE exact Iris writer bytecode " + RasterExperimentSelection.IRIS);
    }
    static Properties read(Path path) throws IOException {
        var properties = new Properties();
        if (Files.exists(path)) try (var input = Files.newInputStream(path)) { properties.load(input); }
        return properties;
    }
    static void write(Path path) throws Exception { write(path, read(path)); }
    static void write(Path path, Properties values) throws Exception {
        initialize();
        PackSelectionTransaction.irisOptionsWriteStarted(path, values);
        invocations++;
        exactWriter.invoke(null, path, values);
        PackSelectionTransaction.irisOptionsWritten(path, values);
    }
    static void replaceBeforeReturn(Path path) throws Exception {
        initialize(); var values = read(path);
        PackSelectionTransaction.irisOptionsWriteStarted(path, values);
        invocations++; exactWriter.invoke(null, path, values);
        Files.writeString(path, "EXTERNAL=9\n");
        PackSelectionTransaction.irisOptionsWritten(path, values);
    }
    static void changeModeBeforeReturn(Path path) throws Exception {
        initialize(); var values = read(path);
        PackSelectionTransaction.irisOptionsWriteStarted(path, values);
        invocations++; exactWriter.invoke(null, path, values);
        Files.setPosixFilePermissions(path, java.nio.file.attribute.PosixFilePermissions.fromString("r--r-----"));
        PackSelectionTransaction.irisOptionsWritten(path, values);
    }
    static Properties partial() {
        var properties = new Properties() {
            @Override public void store(OutputStream output, String comments) throws IOException {
                // Run the native serializer with an output stream failing after 13 actual bytes.
                // The extracted exact Iris method owns opening/truncating/closing the real file
                // and swallowing this IOException. Serialization/body bytes are not fabricated.
                super.store(new java.io.FilterOutputStream(output) {
                    int count;
                    @Override public void write(int value) throws IOException {
                        if (count++ == 13) throw new IOException("Injected partial store I/O failure");
                        out.write(value);
                    }
                    @Override public void write(byte[] values, int offset, int length) throws IOException {
                        for (int i = 0; i < length; i++) write(values[offset + i]);
                    }
                }, comments);
            }
        };
        properties.setProperty("TAA", "true"); return properties;
    }
}

