class TuningPresetMigrationTest {
    private static final Path MANUAL_FIXTURE=Path.of("run-workloads/deep-readiness-20261017/presets-and-tuner/client/shaderlod-tunings/presets/f534d830-184d-487f-a299-58465557f134.json");
    private static final String FIXTURE_SHA256="c57b9ba1934ebf89152ba2c3afd035ca6103a02ff8fad3db526cb901dabf7e88";
    private static final String DEAD_COPY=OptimizationId.DEAD_FRAME_COPY.key();

    private TuningPreset preset(int schema,TuningPreset.Evidence evidence) {
        return new TuningPreset("71c71fd1-a7cc-4a30-9114-c2b03f157966","Migration unit fixture","bsl-shaders","a".repeat(64),
                true,LodPreset.BALANCED,new TuningPreset.Bands(32,96,8,false),
                schema==1?null:new TuningPreset.TerrainPolicy(16,30),
                OptimizationSnapshot.noneRequested().with(OptimizationId.AO_BUDGET,true),
                Map.of("AO","true","TAA","true"),EffectTuningValues.defaults(),Map.of("unit_only","true"),evidence,"2026-10-17T00:00:00Z");
    }
    private JsonObject legacy(int schema,TuningPreset p) {
        var json=JsonParser.parseString(TuningPresetStore.encode(p)).getAsJsonObject();
        json.addProperty("schema",schema);
        if(schema==1)json.remove("terrain_policy");
        json.getAsJsonObject("requests").remove(DEAD_COPY);
        json.getAsJsonObject("requests").remove("translucent_fastpath");json.getAsJsonObject("requests").remove("ao_attenuation");
        json.addProperty("configuration_sha256",p.legacyConfigurationSha256());
        return json;
    }
    private void refuses(JsonObject json,Consumer<JsonObject> corruption) {
        var changed=json.deepCopy();corruption.accept(changed);
        assertThrows(RuntimeException.class,()->TuningPresetStore.decode(changed.toString()));
    }
    private void checksumRefuses(JsonObject json,Consumer<JsonObject> corruption) {
        var changed=json.deepCopy();corruption.accept(changed);
        var error=assertThrows(IllegalArgumentException.class,()->TuningPresetStore.decode(changed.toString()));
        assertEquals("Tuning configuration checksum mismatch",error.getMessage());
    }

    @Test void retainedManualFixtureIsReadOnlyAndItsOriginalChecksumValidatesInBothLegacySchemas()throws Exception {
        var before=Files.readAllBytes(MANUAL_FIXTURE);
        assertEquals(FIXTURE_SHA256,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(before)));
        var original=JsonParser.parseString(Files.readString(MANUAL_FIXTURE)).getAsJsonObject();
        assertEquals(1,original.get("schema").getAsInt());assertEquals(61,original.getAsJsonObject("requests").size());
        var migrated=TuningPresetStore.read(MANUAL_FIXTURE);
        for(int schema:new int[]{1,2}) {
            // Schema 2 permits unspecified terrain; this in-memory variant keeps the captured settings intact.
            var json=original.deepCopy();json.addProperty("schema",schema);
            if(schema==2)json.add("terrain_policy",JsonNull.INSTANCE);
            var p=TuningPresetStore.decode(json.toString());assertEquals(migrated,p);
            assertFalse(p.requests().enabled(OptimizationId.DEAD_FRAME_COPY));
            assertEquals(original.get("configuration_sha256").getAsString(),p.legacyConfigurationSha256());
            assertNotEquals(original.get("configuration_sha256").getAsString(),p.configurationSha256());
            assertNull(p.terrainPolicy());assertEquals(TuningPreset.Provenance.MANUAL,p.evidence().provenance());
            var current=JsonParser.parseString(TuningPresetStore.encode(p)).getAsJsonObject();
            for(String field:new String[]{"id","name","family","original_source_sha256","enabled","engine_preset","bands","native_options","effect_options","context","evidence","created_at"})
                assertEquals(original.get(field),current.get(field),field);
            var requests=current.getAsJsonObject("requests");assertEquals(64,requests.size());requests.remove(DEAD_COPY);requests.remove("translucent_fastpath");requests.remove("ao_attenuation");
            assertEquals(original.getAsJsonObject("requests"),requests);
        }
        assertArrayEquals(before,Files.readAllBytes(MANUAL_FIXTURE));
    }

    @Test void completeOldVectorsMigrateAndOnlyCurrentIdentityIsWritten() {
        for(int schema:new int[]{1,2}) {
            var p=preset(schema,TuningPreset.Evidence.manual());var json=legacy(schema,p);
            assertEquals(61,json.getAsJsonObject("requests").size());
            var migrated=TuningPresetStore.decode(json.toString());assertEquals(p,migrated);
            assertFalse(migrated.requests().enabled(OptimizationId.DEAD_FRAME_COPY));
            assertNotEquals(json.get("configuration_sha256").getAsString(),migrated.configurationSha256());
            var current=JsonParser.parseString(TuningPresetStore.encode(migrated)).getAsJsonObject();
